define({"topics":[{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_18.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e13213","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_5.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e13238","topics":[]},{"title":"Removing the ICN","shortdesc":"<p class=\"shortdesc\">Removes the Image Compute Node (ICN) to replace it or to replace the ICN power supply.<\/p>","href":"t_RemovingtheICNHardware.html","attributes":{"data-id":"id_2001596"},"menu":{"hasChildren":false},"tocID":"id_2001596-d46e13263","topics":[]},{"title":"Installing the ICN","shortdesc":"<p class=\"shortdesc\">Installs the Image Compute Node (ICN) into the cabinet.<\/p>","href":"t_InstallingTheICN.html","attributes":{"data-id":"id_2015721"},"menu":{"hasChildren":false},"tocID":"id_2015721-d46e13288","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_5.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e13313","topics":[]},{"title":"Configuring the ICN - VRE","shortdesc":"<p class=\"shortdesc\">Volume Recon Engine (VRE) configuration reinstalls the software onto the Image Compute Node (ICN). This procedure is also needed after ICN replacement.<\/p>","href":"t_ReconfiguringtheICNVRE_2.html","attributes":{"data-id":"id_2001595"},"menu":{"hasChildren":false},"tocID":"id_2001595-d46e13338","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_16.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e13363","topics":[]}]});